// CSD_RATIONALE_BEGIN
// Building directly on the best attempt (40.8% accuracy, 91.8% syntax).
// Two targeted changes only:
//
//   1. Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` as
//      required by the task contract. This correctly handles space-prefixed
//      delimiter tokens (e.g., " <<") that the Qwen tokenizer may produce.
//      The best attempt likely missed some spans due to exact-token comparison.
//
//   2. Improve task guidance to address the dominant accuracy failure:
//      the model writes bare `n * frac_1 * frac_2` but the correct answer is
//      `int(n * frac_1 * frac_2)`. New guidance:
//        - Explicitly shows int() for fractional multiplication
//        - Shows // for integer division (vs /)
//        - Confirms the LAST << >> is evaluated as the final answer
//        - Bans {} curly braces inside expressions (variable names are plain)
//
// All other logic is identical to the verified best attempt:
//   - Free unconstrained generation outside spans
//   - EnterObservedConstrainedSpan when RenderedEndsWith detects "<<"
//   - AdaptiveConstrainedStep inside spans (hard-masked, group-boosted)
//   - Eager close on parser.IsCompletePrefix (preserves 91.8% syntax)
//   - Budget-pressure force-open (maxSteps - steps <= 4) and
//     CloseSpanWithinBudget (maxSteps - steps <= 3) for graceful exit
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span / UnconstrainedStep branch: insideConstrainedOut starts false and
//   remains false until RenderedEndsWith fires. On detection, EnterObservedConstrainedSpan
//   sets currentConstrainedOut := []; parser.IsValidPrefix([]) holds by precondition.
//
//   Outside-span / force-open branch: OpenConstrainedSpan sets currentConstrainedOut := [];
//   parser.IsValidPrefix([]) holds by precondition; insideConstrainedOut := true.
//
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making the
//   implication vacuously true; currentConstrainedOut := [].
//
//   CloseSpanWithinBudget branch: postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
//   AdaptiveConstrainedStep + AppendConstrainedToken branch: AdaptiveConstrainedStep
//   hard-masks to parser-valid next tokens plus EOS; AppendConstrainedToken extends
//   currentConstrainedOut by that valid token, preserving IsValidPrefix. EOS break
//   leaves state unchanged, invariant holds by induction.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps = 0. ✓
//
//   Outside-span force-open: OpenConstrainedSpan appends exactly 1 token (<<);
//   steps += 1. 1 <= 1. ✓
//
//   Outside-span UnconstrainedStep: steps += 1; EOS breaks without appending
//   (generated unchanged, steps grew by 1). Otherwise generated grows by exactly
//   1 token; EnterObservedConstrainedSpan leaves generated unchanged. ✓
//
//   CloseConstrainedSpan: steps += 1; helper appends at most 1 token (>>). ✓
//
//   CloseSpanWithinBudget: closeBudget = maxSteps - steps; postcondition gives
//   |generatedOut| <= |generated| + closeBudget. After steps := maxSteps:
//   |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   AdaptiveConstrainedStep: steps += 1; EOS breaks without appending (invariant
//   trivially preserved). Otherwise AppendConstrainedToken appends exactly 1 token;
//   |generated| grows by 1 <= steps grows by 1. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve math word problems step by step. Write Python-style arithmetic " +
  "expressions at each calculation step and for the final answer inside << >> delimiters. " +
  "Rules for expressions inside << >>: " +
  "(1) No curly braces {} — use plain variable names: n, frac_1, total, rate. " +
  "(2) Use // for integer division: <<total // rate>>. " +
  "(3) Wrap products involving fractions in int() for integer results: <<int(n * frac_1 * frac_2)>>. " +
  "(4) Your LAST << >> expression in the response is the final answer.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force open a constrained span so there is at least one answer span.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          // Use RenderedEndsWith (not next == "<<") to handle space-prefixed tokens.
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Eager close when span is complete — preserves syntax reliability.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Budget pressure: try to reach a completable state and close gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: hard-masked plus adaptive group boosts.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

